  'songs.editor.notesForStage': { en: 'Notes for stage', tl: 'Notes para sa stage', es: 'Notas para el escenario', pt: 'Notas para o palco', fr: 'Notes pour la scène', it: 'Note per il palco', ko: '무대용 메모', zh: '舞台备注', id: 'Catatan panggung', hi: 'स्टेज के लिए नोट', ta: 'மேடைக் குறிப்பு', ru: 'Заметки для сцены', uk: 'Нотатки для сцени' },
  'songs.editor.notesPlaceholder': { en: 'e.g. Build up, all instruments in · Women only · Repeat twice', tl: 'hal. Pataas, lahat ng instrumento · Babae lang · Ulitin nang dalawang beses', es: 'p. ej. Crecer, entran todos · Solo mujeres · Repetir dos veces', pt: 'ex.: Crescer, todos entram · Só mulheres · Repetir duas vezes', fr: 'ex. Montée, tous les instruments · Femmes seules · Répéter deux fois', it: 'es. Crescendo, tutti gli strumenti · Solo donne · Ripeti due volte', ko: '예: 점점 크게, 모든 악기 · 여성만 · 두 번 반복', zh: '例如 渐强，全体乐器 · 仅女声 · 重复两遍', id: 'mis. Naik, semua alat masuk · Wanita saja · Ulang dua kali', hi: 'जैसे धीरे-धीरे तेज़, सभी वाद्य · केवल महिलाएँ · दो बार दोहराएँ', ta: 'எ.கா. மெல்ல உயர்த்து, எல்லா இசைக்கருவிகளும் · பெண்கள் மட்டும் · இருமுறை', ru: 'напр. Нарастание, все инструменты · Только женщины · Повторить дважды', uk: 'напр. Наростання, усі інструменти · Лише жінки · Повторити двічі' },
