  'songs.editor.addSlideHint': { en: 'Alt+Enter in a slide splits it at the cursor', tl: 'Alt+Enter sa slide para hatiin ito sa cursor', es: 'Alt+Enter en una diapositiva la divide en el cursor', pt: 'Alt+Enter num slide divide no cursor', fr: 'Alt+Entrée dans une diapo la coupe au curseur', it: 'Alt+Invio in una slide la divide al cursore', ko: '슬라이드에서 Alt+Enter로 커서 위치에서 나누기', zh: '在幻灯片中按 Alt+Enter 于光标处拆分', id: 'Alt+Enter di slide membaginya di kursor', hi: 'स्लाइड में Alt+Enter कर्सर पर उसे बाँटता है', ta: 'ஸ்லைடில் Alt+Enter கர்சரில் பிரிக்கும்', ru: 'Alt+Enter в слайде делит его по курсору', uk: 'Alt+Enter у слайді ділить його за курсором' },
