  'songs.find.buttonHint': { en: "Search lyrics online, or import from SongSelect and ChordPro files", tl: "Maghanap ng lyrics online, o mag-import mula sa SongSelect at ChordPro", es: "Buscar letras en internet o importar de SongSelect y archivos ChordPro", pt: "Buscar letras na internet ou importar do SongSelect e de arquivos ChordPro", fr: "Chercher des paroles en ligne, ou importer depuis SongSelect et des fichiers ChordPro", it: "Cerca testi online o importa da SongSelect e file ChordPro", ko: "온라인에서 가사를 찾거나 SongSelect·ChordPro 파일에서 가져오기", zh: "在线搜索歌词，或从 SongSelect 和 ChordPro 文件导入", id: "Cari lirik online, atau impor dari SongSelect dan file ChordPro", hi: "ऑनलाइन बोल खोजें, या SongSelect और ChordPro फ़ाइलों से इम्पोर्ट करें", ta: "இணையத்தில் பாடல் வரிகளைத் தேடு, அல்லது SongSelect, ChordPro கோப்புகளிலிருந்து இறக்கு", ru: "Искать слова в интернете или импортировать из SongSelect и файлов ChordPro", uk: "Шукати слова в інтернеті або імпортувати з SongSelect і файлів ChordPro" },
  'songs.find.searchOnline': { en: "Search online for “{title}”", tl: "Hanapin online ang “{title}”", es: "Buscar “{title}” en internet", pt: "Buscar “{title}” na internet", fr: "Chercher « {title} » en ligne", it: "Cerca “{title}” online", ko: "온라인에서 “{title}” 찾기", zh: "在线搜索“{title}”", id: "Cari “{title}” secara online", hi: "“{title}” ऑनलाइन खोजें", ta: "“{title}” இணையத்தில் தேடு", ru: "Искать «{title}» в интернете", uk: "Шукати «{title}» в інтернеті" },
  'songs.find.title': { en: "Find a song", tl: "Maghanap ng kanta", es: "Buscar una canción", pt: "Buscar uma música", fr: "Trouver un chant", it: "Trova un canto", ko: "노래 찾기", zh: "查找歌曲", id: "Cari lagu", hi: "गीत खोजें", ta: "பாடலைத் தேடு", ru: "Найти песню", uk: "Знайти пісню" },
  'songs.find.placeholder': { en: "Song title, artist or a line of the lyrics", tl: "Pamagat, artist o isang linya ng lyrics", es: "Título, artista o una línea de la letra", pt: "Título, artista ou um verso da letra", fr: "Titre, artiste ou une ligne des paroles", it: "Titolo, artista o un verso del testo", ko: "제목, 아티스트 또는 가사 한 줄", zh: "歌名、歌手或一句歌词", id: "Judul, artis, atau satu baris lirik", hi: "गीत का नाम, कलाकार या बोल की एक पंक्ति", ta: "பாடல் தலைப்பு, கலைஞர் அல்லது ஒரு வரி", ru: "Название, исполнитель или строка из песни", uk: "Назва, виконавець або рядок із пісні" },
  'songs.find.search': { en: "Search", tl: "Hanapin", es: "Buscar", pt: "Buscar", fr: "Chercher", it: "Cerca", ko: "검색", zh: "搜索", id: "Cari", hi: "खोजें", ta: "தேடு", ru: "Найти", uk: "Шукати" },
